        counts[0] = 0.0
        observed_counts = counts[counts > 0]
        median_count = float(np.median(observed_counts)) if observed_counts.size else 1.0
        input_scale = np.clip(
            (median_count / np.maximum(counts, 1.0)) ** 0.1, 0.75, 1.25
        ).astype(np.float32)
        input_scale[0] = 0.0
